  sfw_note_head_ambient: { en: "Head/ambient context at diagnosis: {head} psi head with {ambient}°F ambient.", es: "Contexto de descarga/ambiente en el diagnóstico: {head} psi de descarga con {ambient}°F ambiente." },
  sfw_risk_cond_fan: { en: "Outdoor airflow callbacks happen when coil condition or voltage issues are missed.", es: "Los retornos por flujo de aire exterior ocurren cuando se pasan por alto problemas de condición del serpentín o voltaje." },
  sfw_watch_evap_fan: { en: "Watch airflow, frost return, and drain condition after operation.", es: "Vigila el flujo de aire, el retorno de escarcha, y la condición del drenaje después de operar." },
  sfw_recheck_evap_fan: { en: "Recheck fan operation and airflow path after the box or space pulls down.", es: "Reverifica la operación del ventilador y la ruta de flujo de aire después de que el cuarto o espacio baje de temperatura." },
  sfw_note_air_split: { en: "Air split context at diagnosis: {value}°F.", es: "Contexto de split de aire en el diagnóstico: {value}°F." },
  sfw_risk_evap_fan: { en: "Fan-related callbacks happen when the real issue is still defrost, drain, or blocked airflow.", es: "Los retornos relacionados con el ventilador ocurren cuando el problema real sigue siendo descongelamiento, drenaje, o flujo de aire bloqueado." },
  sfw_watch_defrost_heater: { en: "Watch the next full defrost cycle and confirm the ice pattern does not return.", es: "Vigila el siguiente ciclo completo de descongelamiento y confirma que el patrón de hielo no regrese." },
  sfw_recheck_defrost_heater: { en: "Recheck termination, control output, and drain path.", es: "Reverifica la terminación, la salida de control, y la ruta de drenaje." },
  sfw_note_box_temp: { en: "Box temperature context: {value}°F.", es: "Contexto de temperatura del cuarto: {value}°F." },
  sfw_risk_defrost_heater: { en: "Heater replacement alone may not solve the call if termination/control logic is wrong.", es: "Reemplazar solo el calentador puede no resolver la llamada si la lógica de terminación/control está mal." },
  sfw_watch_defrost_term: { en: "Watch the next timed/initiated defrost and confirm heater/fan sequence.", es: "Vigila el siguiente descongelamiento programado/iniciado y confirma la secuencia del calentador/ventilador." },
  sfw_recheck_defrost_term: { en: "Recheck fan delay, termination state, and drain heat path.", es: "Reverifica el retardo del ventilador, el estado de terminación, y la ruta de calor de drenaje." },
  sfw_risk_defrost_term: { en: "Defrost callbacks happen when timing logic is not verified against actual ice pattern.", es: "Los retornos de descongelamiento ocurren cuando la lógica de tiempo no se verifica contra el patrón real de hielo." },
  sfw_watch_txv: { en: "Watch superheat/subcool trend and frost pattern after the system stabilizes.", es: "Vigila la tendencia de sobrecalentamiento/subenfriamiento y el patrón de escarcha después de que el sistema se estabilice." },
  sfw_recheck_txv: { en: "Recheck airflow and restriction path before assuming the feed path is fixed.", es: "Reverifica el flujo de aire y la ruta de restricción antes de asumir que la ruta de alimentación está reparada." },
  sfw_note_shsc: { en: "SH/SC context at diagnosis: SH {sh}°F, SC {sc}°F.", es: "Contexto de SE/SC en el diagnóstico: SE {sh}°F, SC {sc}°F." },
  sfw_risk_txv: { en: "Metering-device callbacks happen when airflow or restriction was the real cause.", es: "Los retornos del dispositivo de medición ocurren cuando el flujo de aire o la restricción fueron la causa real." },
  sfw_watch_blower: { en: "Watch airflow, split, and drain safety behavior after the repair.", es: "Vigila el flujo de aire, el split, y el comportamiento de la seguridad de drenaje después de la reparación." },
  sfw_recheck_blower: { en: "Recheck amp draw, wheel condition, and board/relay output.", es: "Reverifica el consumo de amperaje, la condición de la rueda, y la salida de la tarjeta/relé." },
  sfw_risk_blower: { en: "Blower callbacks happen when the true issue is control output or drain interruption.", es: "Los retornos del soplador ocurren cuando el problema real es la salida de control o la interrupción del drenaje." },
  sfw_watch_float: { en: "Watch drain flow and whether the control interruption returns.", es: "Vigila el flujo de drenaje y si la interrupción de control regresa." },
  sfw_recheck_float: { en: "Recheck actual drain condition and switch state.", es: "Reverifica la condición real del drenaje y el estado del interruptor." },
  sfw_risk_float: { en: "Drain safety callbacks happen when the water problem was not corrected.", es: "Los retornos de seguridad de drenaje ocurren cuando el problema de agua no se corrigió." },
  sfw_watch_ignitor: { en: "Watch the next heat cycle through ignition and flame prove.", es: "Vigila el siguiente ciclo de calor durante la ignición y la comprobación de flama." },
  sfw_recheck_ignitor: { en: "Recheck board output and full heat sequence if symptoms return.", es: "Reverifica la salida de la tarjeta y la secuencia completa de calor si los síntomas regresan." },
  sfw_risk_ignitor: { en: "Ignition callbacks happen when the full safety chain is not checked.", es: "Los retornos de ignición ocurren cuando no se revisa la cadena completa de seguridad." },
  sfw_watch_flame: { en: "Watch flame proving through multiple heat cycles.", es: "Vigila la comprobación de flama durante múltiples ciclos de calor." },
  sfw_recheck_flame: { en: "Recheck flame signal, burner carryover, and ignition quality.", es: "Reverifica la señal de flama, el arrastre del quemador, y la calidad de ignición." },
  sfw_risk_flame: { en: "Flame-sense callbacks happen when ignition quality or grounding is still weak.", es: "Los retornos de detección de flama ocurren cuando la calidad de ignición o la conexión a tierra siguen débiles." },
  sfw_watch_pressure_switch: { en: "Watch the next full heat call and confirm pressure-proving stays stable.", es: "Vigila la siguiente llamada completa de calor y confirma que la comprobación de presión se mantenga estable." },
  sfw_recheck_pressure_switch: { en: "Recheck inducer operation, tubing, venting, and condensate path.", es: "Reverifica la operación del inductor, la tubería, la ventilación, y la ruta de condensado." },
  sfw_risk_pressure_switch: { en: "Pressure-switch callbacks happen when draft or drain issues were not corrected.", es: "Los retornos del interruptor de presión ocurren cuando no se corrigieron problemas de tiro o drenaje." },
  sfw_watch_water: { en: "Watch the next full sequence and confirm water-side timing stays correct.", es: "Vigila la siguiente secuencia completa y confirma que el tiempo del lado de agua se mantenga correcto." },
  sfw_recheck_water: { en: "Recheck component response during the expected cycle.", es: "Reverifica la respuesta del componente durante el ciclo esperado." },
  sfw_risk_water: { en: "Sequence callbacks happen when the wrong side of the system was blamed.", es: "Los retornos de secuencia ocurren cuando se culpó al lado equivocado del sistema." },
  sfw_watch_walkin: { en: "Watch actual box pull-down and next defrost cycle.", es: "Vigila el enfriamiento real del cuarto y el siguiente ciclo de descongelamiento." },
  sfw_watch_icing: { en: "Watch for return ice pattern, drain issues, and airflow drop after the repair.", es: "Vigila el patrón de hielo que regresa, problemas de drenaje, y caída de flujo de aire después de la reparación." },
  sfw_risk_icing: { en: "Freeze-up complaints often return if airflow/defrost/feed verification was incomplete.", es: "Las quejas de congelamiento suelen regresar si la verificación de flujo de aire/descongelamiento/alimentación quedó incompleta." },
