  // ── buildPlainEnglishCloseoutReadingsInterpretation() ────────
  pce_high_sh_low_sc_note: { en: "High superheat with low subcool points toward underfeed, undercharge, restriction, or airflow verification.", es: "El sobrecalentamiento alto con subenfriamiento bajo apunta hacia subalimentación, carga baja, restricción, o verificación de flujo de aire." },
  pce_high_sh_low_sc_followup: { en: "Verify airflow and refrigerant feed path before repeating major part replacement.", es: "Verifica el flujo de aire y la ruta de alimentación de refrigerante antes de repetir un reemplazo mayor de partes." },
  pce_low_sh_high_sc_note: { en: "Low superheat with high subcool points toward floodback, overfeed, or an airflow-related issue.", es: "El sobrecalentamiento bajo con subenfriamiento alto apunta hacia retorno de líquido, sobrealimentación, o un problema relacionado con el flujo de aire." },
  pce_low_sh_high_sc_followup: { en: "Check airflow and metering behavior before condemning compressor or charge condition.", es: "Revisa el flujo de aire y el comportamiento de medición antes de condenar el compresor o la condición de carga." },
  pce_high_sh_high_sc_note: { en: "High superheat with high subcool can point toward a liquid-line restriction or feed issue.", es: "El sobrecalentamiento alto con subenfriamiento alto puede apuntar hacia una restricción en la línea de líquido o un problema de alimentación." },
  pce_high_sh_high_sc_followup: { en: "Check for restriction points and liquid line temperature drop before replacing components.", es: "Revisa puntos de restricción y la caída de temperatura de la línea de líquido antes de reemplazar componentes." },
  pce_sh_sc_balanced_note: { en: "Superheat and subcool look reasonably balanced, so controls, airflow, or electrical checks may matter more than a major charge correction.", es: "El sobrecalentamiento y el subenfriamiento se ven razonablemente equilibrados, así que las revisiones de controles, flujo de aire, o eléctricas pueden importar más que una corrección mayor de carga." },
  pce_high_sh_only_note: { en: "High superheat suggests the evaporator may be starved or airflow may need verified.", es: "El sobrecalentamiento alto sugiere que el evaporador puede estar hambriento o que se necesita verificar el flujo de aire." },
  pce_high_sh_only_followup: { en: "Verify feed path, airflow, and possible restriction before changing major parts.", es: "Verifica la ruta de alimentación, el flujo de aire, y posible restricción antes de cambiar partes mayores." },
  pce_low_sh_only_note: { en: "Low superheat suggests floodback, overfeed, or airflow issues should be checked.", es: "El sobrecalentamiento bajo sugiere que se deben revisar retorno de líquido, sobrealimentación, o problemas de flujo de aire." },
  pce_low_sh_only_followup: { en: "Check evaporator airflow and metering behavior before adding charge or replacing compressors.", es: "Revisa el flujo de aire del evaporador y el comportamiento de medición antes de agregar carga o reemplazar compresores." },
  pce_low_sc_only_note: { en: "Low subcool suggests undercharge or liquid feed verification may still be needed.", es: "El subenfriamiento bajo sugiere que aún puede ser necesaria la verificación de carga baja o alimentación de líquido." },
  pce_high_sc_only_note: { en: "High subcool suggests overcharge or a restriction should be ruled out.", es: "El subenfriamiento alto sugiere que se debe descartar sobrecarga o una restricción." },
  pce_low_split_note: { en: "The return-to-supply temperature split is weak, which points toward airflow, control, or charge/feed verification.", es: "El split de temperatura de retorno a suministro es débil, lo cual apunta hacia verificación de flujo de aire, control, o carga/alimentación." },
  pce_low_split_followup: { en: "Verify indoor airflow and compare current split against operating conditions before closing the call.", es: "Verifica el flujo de aire interior y compara el split actual contra las condiciones de operación antes de cerrar la llamada." },
  pce_high_split_note: { en: "The return-to-supply temperature split is very high, so airflow restriction, icing, or low-load conditions should be considered.", es: "El split de temperatura de retorno a suministro es muy alto, así que se deben considerar restricción de flujo de aire, congelamiento, o condiciones de carga baja." },
  pce_high_split_followup: { en: "Check filter, coil, fan performance, and frost pattern before repeating the same repair.", es: "Revisa el filtro, el serpentín, el desempeño del ventilador, y el patrón de escarcha antes de repetir la misma reparación." },
  pce_head_ambient_note: { en: "Head pressure is high relative to ambient, which points toward heat rejection issues first.", es: "La presión de descarga está alta en relación al ambiente, lo cual apunta primero hacia problemas de rechazo de calor." },
  pce_head_ambient_followup: { en: "Verify condenser airflow, fan operation, coil cleanliness, and ambient/load conditions.", es: "Verifica el flujo de aire del condensador, la operación del ventilador, la limpieza del serpentín, y las condiciones ambientales/de carga." },
  pce_box_temp_note: { en: "Box temperature is {value}°F, so defrost performance, control strategy, and actual box load should be part of the closeout decision.", es: "La temperatura del cuarto es {value}°F, así que el desempeño de descongelamiento, la estrategia de control, y la carga real del cuarto deben ser parte de la decisión de cierre." },

