  // ── Refrigerant Reference ─────────────────────────────────────
  refr_a2l_banner_title: { en: "⚠️ A2L Transition:", es: "⚠️ Transición A2L:" },
  refr_a2l_banner_body: { en: "R-454B and R-32 are now required for new residential equipment in the US. All techs servicing new equipment must be familiar with A2L handling requirements. A2L refrigerants are mildly flammable — standard R-410A procedures are not sufficient.", es: "R-454B y R-32 ahora son requeridos para equipo residencial nuevo en EE.UU. Todos los técnicos que dan servicio a equipo nuevo deben estar familiarizados con los requisitos de manejo A2L. Los refrigerantes A2L son ligeramente inflamables — los procedimientos estándar de R-410A no son suficientes." },
  refr_search_placeholder: { en: "Search by refrigerant name, use, or replaces...", es: "Buscar por nombre de refrigerante, uso, o reemplazo..." },
